What does this program print?

```zig
const std = @import("std");

pub fn main() void {
    const word = "kayak";
    const is_palindrome = blk: {
        var i: usize = 0;
        while (i < word.len / 2) : (i += 1) {
            if (word[i] != word[word.len - 1 - i]) break :blk false;
        }
        break :blk true;
    };
    const label = switch (word.len) {
        0 => "empty",
        1...4 => "short",
        else => "long",
    };
    std.debug.print("{} {s}\n", .{ is_palindrome, label });
}
```
